def binaria(xs, alvo):
    lo,hi=0,len(xs)-1
    while lo<=hi:
        m=(lo+hi)//2
        if xs[m]==alvo:
            return m
        if xs[m]<alvo:
            lo=m+1
        else:
            hi=m-1
    return -1

