def lru_simula(capacidade, ops):
    from collections import OrderedDict
    c=OrderedDict(); out=[]
    for op in ops:
        if op[0]=='set':
            c[op[1]]=op[2]; c.move_to_end(op[1])
            if len(c)>capacidade:
                c.popitem(last=False)
        else:
            if op[1] in c:
                c.move_to_end(op[1]); out.append(c[op[1]])
            else:
                out.append(None)
    return out

